package br.com.gestaoservicos.empresa.controller;
import br.com.gestaoservicos.empresa.dto.*; import br.com.gestaoservicos.empresa.service.EmpresaService; import br.com.gestaoservicos.security.ContextoUnidade; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/v1/empresas") public class EmpresaController {private final EmpresaService service; public EmpresaController(EmpresaService s){service=s;} private UUID unidade(){return ContextoUnidade.atual().map(ContextoUnidade.Selecao::unidadeId).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Selecione uma unidade"));} @GetMapping @PreAuthorize("@autorizacaoUnidade.possuiAlgumPerfil('ADMIN','GESTOR','OPERADOR','CONSULTA')") List<EmpresaResponseDTO> listar(){return service.listar(unidade());} @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("@autorizacaoUnidade.possuiAlgumPerfil('ADMIN','GESTOR')") EmpresaResponseDTO criar(@Valid @RequestBody EmpresaRequestDTO r){return service.criar(unidade(),r);} @PutMapping("/{id}") @PreAuthorize("@autorizacaoUnidade.possuiAlgumPerfil('ADMIN','GESTOR')") EmpresaResponseDTO atualizar(@PathVariable UUID id,@Valid @RequestBody EmpresaRequestDTO r){return service.atualizar(unidade(),id,r);} @PostMapping("/{id}/inativar") @PreAuthorize("@autorizacaoUnidade.possuiAlgumPerfil('ADMIN','GESTOR')") EmpresaResponseDTO inativar(@PathVariable UUID id){return service.status(unidade(),id,false);} @PostMapping("/{id}/reativar") @PreAuthorize("@autorizacaoUnidade.possuiAlgumPerfil('ADMIN','GESTOR')") EmpresaResponseDTO reativar(@PathVariable UUID id){return service.status(unidade(),id,true);}}
